/* =============================================================================
   params.js — the single source of truth for every knob on this page.
   -----------------------------------------------------------------------------
   Nothing here touches the DOM, so it can be imported by node for validation
   (tools/validate.mjs) as well as by the browser.

   Each entry:
     k   uniform / config key, without the u_ prefix
     u   uniform name actually declared in js/shaders/globals.glsl
         (or null when the knob is CPU-side only: HUD text, quality, etc.)
     t   type: F float · I int · V3 vec3 · V4 vec4 · S select · B bool · C colour
     tab UI tab · grp sub-heading inside the tab · lvl 0 core, 1 advanced, 2 expert
     m   modes the knob matters for (undefined = all)
     a   what it does to the picture, in one line (used by the HUD legend,
         the command palette and the "Field notes" pane) */
'use strict';

export const MODES = [
  { id: 'substrata', name: 'Substrata', ico: '▤', tag: 'clay → trees · sand → shells',
    blurb: 'A slow rolling terrain where every animate thing leaves a mark and the ground is the only one keeping records.' },
  { id: 'director', name: 'Director', ico: '⫽', tag: 'nematic liquid crystal',
    blurb: 'Rod molecules on a leash: tilt, twist, splay, bend. The electric field tips them; the light reads the tipping.' },
  { id: 'conoscope', name: 'Conoscope', ico: '◎', tag: 'Berreman / Jones slabs',
    blurb: 'The microscope crosses its polarisers and you look through the cell: the Maltese cross, the interference rings, the twist told in colour.' },
  { id: 'hologram', name: 'Hologram', ico: '❋', tag: 'phase → wavefront',
    blurb: 'Every pixel of a liquid-crystal panel delays the wavefront a little. Delay becomes diffraction becomes depth.' },
  { id: 'crystal', name: 'Crystal', ico: '❖', tag: 'anisotropy made visible',
    blurb: 'One mineral that slows one polarisation more than the other, and so paints the sky inside a stone.' },
  { id: 'weathering', name: 'Weathering', ico: '≋', tag: 'rock → clay',
    blurb: 'Feldspar becomes kaolinite at a rate you can barely see, and the terrain rearranges itself around the same three ideas.' },
  { id: 'causal', name: 'Causal', ico: '⇶', tag: 'antecedent → hinge → event',
    blurb: 'The shape the conversation kept rediscovering: a dormant substrate, a slow mechanism, a drastic emergent result.' },
];

